namespace sv_701217267cb143e698d5ecd2f443a348.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (one instance per circuit) that holds theme state
/// and notifies all subscribers when it changes.
/// </summary>
public class ThemeService
{
    private ThemeMode _mode = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Mode
    {
        get => _mode;
        set
        {
            if (_mode == value) return;
            _mode = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    /// <summary>
    /// Apply multiple changes and fire a single notification.
    /// </summary>
    public void Update(ThemeMode mode, string accentColor)
    {
        _mode = mode;
        _accentColor = accentColor;
        NotifyChanged();
    }

    private void NotifyChanged() => OnChange?.Invoke();
}

