@* Interactive island — renders with its own InteractiveServer circuit
   even though the parent layout is static SSR. *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<span class="badge rounded-pill"
      style="background-color: @Theme.AccentColor; color: white; font-size: 0.8rem;">
    @Theme.Mode
</span>

@code {
    protected override void OnInitialized()
    {
        Theme.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChanged;
    }
}

@* Interactive island for the sidebar — lets users toggle the theme
   without navigating to settings. *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<div class="px-3 py-2">
    <label class="form-label text-light mb-1" style="font-size: 0.85rem;">Theme</label>
    <select class="form-select form-select-sm"
            value="@Theme.Mode"
            @onchange="OnModeChanged">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        Theme.OnChange += HandleThemeChanged;
    }

    private void OnModeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
        {
            Theme.Mode = mode;
        }
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <select class="form-select"
                    value="@Theme.Mode"
                    @onchange="OnModeChanged">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    <option value="@mode">@mode</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color"
                       class="form-control form-control-color"
                       value="@Theme.AccentColor"
                       @onchange="OnAccentChanged" />
                <span class="text-muted">@Theme.AccentColor</span>
            </div>
        </div>

        <div class="alert alert-info mb-0" role="alert"
             style="border-left: 4px solid @Theme.AccentColor;">
            Current theme: <strong>@Theme.Mode</strong> &middot;
            Accent: <span style="color: @Theme.AccentColor;">@Theme.AccentColor</span>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        Theme.OnChange += HandleThemeChanged;
    }

    private void OnModeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
        {
            Theme.Mode = mode;
        }
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        Theme.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
